function startMode(mode){stop();state.mode=mode;rounds=order.map(row=>row.map(i=>modes[mode].ids[i]));state.round=0;state.answers=[];state.type=null;document.body.dataset.mode=mode;$('quiz-side').replaceChildren(document.createTextNode(mode==='front'?'表':'裏'),Object.assign(document.createElement('span'),{textContent:mode==='front'?'OMOTE / LIGHT':'URA / SHADE'}));$('quiz-title').innerHTML=mode==='front'?'<span class="title-line">好き！が</span><span class="title-line">あふれる</span><span class="title-line title-emphasis">わたし。</span>':'<span class="title-line">言えない</span><span class="title-line">気持ちと</span><span class="title-line title-emphasis">わたし。</span>';$('quiz-mode').textContent=`${modes[mode].label} / ${modes[mode].camera}`;show('quiz');if(state.ready)renderRound()}
