function renderRound(focus=false){state.locked=false;const number=String(state.round+1).padStart(2,'0');$('round-number').textContent=number;$('gallery-index').textContent=`QUESTION ${number} / 06`;$('question-caption').textContent=questions[state.round];$('back').hidden=state.round===0;$('progress').setAttribute('aria-label',`全6問のうち${state.round+1}問目`);$('progress').replaceChildren(...rounds.map((_,i)=>{const step=document.createElement('span');step.className=`progress-step ${i<state.round?'done':i===state.round?'active':''}`;return step}));$('photo-options').replaceChildren(...rounds[state.round].map((id,i)=>{const p=photoById(id);const button=document.createElement('button');button.className='landscape';button.dataset.photo=id;button.setAttribute('aria-label',`${'ABCD'[i]} ${p.name}を選ぶ`);const frame=document.createElement('span');frame.className='landscape-image';frame.style.display='block';const img=document.createElement('img');img.src=p.src;img.alt=p.name;const mark=document.createElement('span');mark.className='choose-mark';mark.setAttribute('aria-hidden','true');mark.textContent='＋';frame.append(img,mark);const caption=document.createElement('span');caption.className='landscape-caption';const letter=document.createElement('span');letter.className='option-letter';letter.textContent='ABCD'[i];const name=document.createElement('span');name.textContent=p.name;caption.append(letter,name);button.append(frame,caption);button.onclick=()=>choosePhoto(id);return button}));announce(`${state.round+1}問目。4枚から好きな景色をひとつ選んでください。`);if(focus)$('photo-options').querySelector('button').focus({preventScroll:true})}
function choosePhoto(id){if(state.view!=='quiz'||!state.ready||state.locked||!rounds[state.round]?.includes(id))return false;state.locked=true;state.answers[state.round]=id;state.answers.length=state.round+1;document.querySelectorAll('.landscape').forEach(button=>{button.disabled=true;const selected=button.dataset.photo===id;button.classList.toggle('selected',selected);button.classList.toggle('not-selected',!selected);if(selected)button.querySelector('.choose-mark').textContent='✓'});const run=state.run;state.transition=setTimeout(()=>{if(run!==state.run||state.view!=='quiz')return;if(state.round===rounds.length-1)finish();else{state.round++;renderRound()}},reducedMotion()?0:720);return true}
