function diagnose(answers){if(answers.length!==rounds.length||answers.some((id,i)=>!rounds[i].includes(id)))throw Error('Six valid choices are required');const counts=Object.fromEntries(Object.keys(types).map(key=>[key,0]));answers.forEach(id=>counts[photoById(id).group]++);const maximum=Math.max(...Object.values(counts));const last=answers.slice().reverse().find(id=>counts[photoById(id).group]===maximum);return photoById(last).group}
