function setRepresentative(p){state.representative=p;document.querySelector('.card-front').setAttribute('aria-hidden','false');document.querySelector('.card-back').setAttribute('aria-hidden','true');$('result-card').classList.remove('flipped');$('result-card').setAttribute('aria-label','カードを裏返してもうひとつの言葉を読む');$('result-image').src=p.src;$('result-image').alt=p.name;$('front-copy').textContent=state.mode==='back'?p.back:p.front;$('back-copy').textContent=state.mode==='back'?p.front:p.back;$('result-photo-number').textContent=`PHOTO ${String(p.index+1).padStart(2,'0')}`;markSelected()}
