function flip(){const flipped=$('result-card').classList.toggle('flipped');document.querySelector('.card-front').setAttribute('aria-hidden',String(flipped));document.querySelector('.card-back').setAttribute('aria-hidden',String(!flipped));$('result-card').setAttribute('aria-label',flipped?'カードを表に戻す':'カードを裏返してもうひとつの言葉を読む');announce(flipped?$('back-copy').textContent:$('front-copy').textContent)}
function saveNote(event){event.preventDefault();const text=$('note').value.trim();if(!text){$('save-status').textContent='浮かんだ言葉をひとこと、書いてみてください。';$('note').focus();return}const note={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),text:text.slice(0,160),photo:state.representative.id,type:`${modes[state.mode].label}：${$('result-title').textContent}`,date:Date.now()};const next=[...notes,note].slice(-60);try{localStorage.setItem('kurukuru-words-v1',JSON.stringify(next));notes=next;countNotes();$('save-status').textContent='ことばを残しました。「残したことば」から読めます。';$('save-note').disabled=true}catch{$('save-status').textContent='この端末では保存できませんでした。言葉をコピーして残してください。'}}
function renderWall(){$('wall-cards').replaceChildren();if(!notes.length){const empty=document.createElement('div');empty.className='empty-wall';empty.textContent='まだ、ことばはありません。\n景色を選んだあと、最初のひとことを残してみてください。';empty.style.whiteSpace='pre-line';$('wall-cards').append(empty);return}notes.slice().reverse().forEach(n=>{const p=photoById(n.photo);const card=document.createElement('article');card.className='word-card';const img=document.createElement('img');img.src=p.src;img.alt=p.name;const words=document.createElement('p');words.textContent=n.text;const label=document.createElement('small');label.textContent=n.type;const del=document.createElement('button');del.className='delete-note';del.textContent='このことばを消す';del.onclick=()=>{const next=notes.filter(x=>x.id!==n.id);try{localStorage.setItem('kurukuru-words-v1',JSON.stringify(next));notes=next;countNotes();renderWall()}catch{announce('保存先を更新できませんでした。')}};card.append(img,words,label,del);$('wall-cards').append(card)})}
document.querySelectorAll('[data-home-mode]').forEach(button=>button.onclick=()=>{if(state.view==='entrance'||state.view==='back-home')openHome(button.dataset.homeMode)});$('backdoor').onclick=()=>openHome('back');$('frontdoor').onclick=()=>openHome('front');document.body.dataset.mode='front';document.querySelectorAll('[data-start-mode]').forEach(button=>button.onclick=()=>startMode(button.dataset.startMode));$('other-mode').onclick=()=>openHome(state.mode==='front'?'back':'front');$('home-link').onclick=e=>{e.preventDefault();start()};$('back').onclick=previous;$('wall-link').onclick=()=>{stop();renderWall();show('wall')};$('wall-start').onclick=start;$('restart').onclick=start;$('result-card').onclick=flip;$('note-form').onsubmit=saveNote;$('note').oninput=()=>{$('char-count').textContent=`${$('note').value.length} / 160`;$('save-note').disabled=false;$('save-status').textContent=''};
document.addEventListener('keydown',e=>{if(state.view!=='quiz'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea'))return;const i=['1','2','3','4'].indexOf(e.key);if(i>=0){e.preventDefault();choosePhoto(rounds[state.round][i])}});
